const cfg = $('Config').first().json;
const csvPath = cfg.csv_path;
const grupoAD = cfg.grupo_ad;
// Aspas duplas nos parametros para suportar espacos (ex: "Aprovadores GLPI")
const comando = `powershell.exe -ExecutionPolicy Bypass -File "C:\\Scripts\\Sync_Aprovadores.ps1" -CsvPath "${csvPath}" -GrupoAD "${grupoAD}"`;
return [{ json: { comando, csv_path: csvPath, grupo_ad: grupoAD } }];

const inJson = $input.first().json;
const stdout = inJson.stdout || '';
const stderr = inJson.stderr || '';
const sshError = inJson.error || inJson.errorMessage;

let resultado;
if (sshError && !stdout) {
  resultado = { sucesso: false, erro: 'Falha SSH no servidor AD: ' + sshError };
} else if (!stdout.trim()) {
  resultado = { sucesso: false, erro: 'Servidor AD nao retornou saida. stderr: ' + (stderr || 'vazio') };
} else {
  // Defensivo: extrair ULTIMO objeto JSON valido do stdout
  // (PowerShell as vezes imprime warnings/progress antes do JSON final)
  resultado = null;
  const candidatos = stdout.match(/\{[\s\S]*\}\s*$/);
  if (candidatos) {
    try { resultado = JSON.parse(candidatos[0]); } catch(_) {}
  }
  if (!resultado) {
    try { resultado = JSON.parse(stdout.trim()); } catch(_) {}
  }
  if (!resultado) {
    const linhas = stdout.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    for (let i = linhas.length - 1; i >= 0; i--) {
      const l = linhas[i];
      if (l.startsWith('{') && l.endsWith('}')) {
        try { resultado = JSON.parse(l); break; } catch(_) {}
      }
    }
  }
  if (!resultado) {
    resultado = { sucesso: false, erro: 'Saida invalida do PowerShell (sem JSON valido): ' + stdout.substring(Math.max(0, stdout.length - 300)) };
  }
}

// Resumo legivel
let resumo = '';
if (resultado.sucesso) {
  resumo = `Sync OK em ${resultado.grupo}. ` +
           `CSV=${resultado.csv_total} | AD antes=${resultado.ad_antes} -> depois=${resultado.ad_depois}. ` +
           `+${(resultado.adicionados || []).length} adicionados, ` +
           `-${(resultado.removidos || []).length} removidos, ` +
           `${(resultado.ignorados || []).length} ignorados, ` +
           `${(resultado.erros || []).length} erros.`;
} else {
  resumo = 'FALHA: ' + (resultado.erro || 'erro desconhecido');
}

return [{ json: {
  sucesso: !!resultado.sucesso,
  resumo,
  resultado,
  stdout_raw: stdout.substring(0, 2000),
  stderr_raw: stderr.substring(0, 1000)
}}];
